    std::tuple<int, gocpp::error> rec::WriteString(genericReplacer* r, io::Writer w, gocpp::string s)
    {
        int n;
        gocpp::error err;
        auto sw = getStringWriter(w);
        int last = {};
        int wn = {};
        bool prevMatchEmpty = {};
        for(auto i = 0; i <= len(s); )
        {
            // Fast path: s[i] is not a prefix of any pattern.
            if(i != len(s) && r->root.priority == 0)
            {
                auto index = int(r->mapping[s[i]]);
                if(index == r->tableSize || r->root.table[index] == nullptr)
                {
                    i++;
                    continue;
                }
            }

            // Ignore the empty match iff the previous loop found the empty match.
            auto [val, keylen, match] = rec::lookup(gocpp::recv(r), s.make_slice(i), prevMatchEmpty);
            prevMatchEmpty = match && keylen == 0;
            if(match)
            {
                std::tie(wn, err) = rec::WriteString(gocpp::recv(sw), s.make_slice(last, i));
                n += wn;
                if(err != nullptr)
                {
                    return {n, err};
                }
                std::tie(wn, err) = rec::WriteString(gocpp::recv(sw), val);
                n += wn;
                if(err != nullptr)
                {
                    return {n, err};
                }
                i += keylen;
                last = i;
                continue;
            }
            i++;
        }
        if(last != len(s))
        {
            std::tie(wn, err) = rec::WriteString(gocpp::recv(sw), s.make_slice(last));
            n += wn;
        }
        return {n, err};
    }

